-- Conteúdo inicial em espanhol (mescla a chave "es" nos textos já semeados na 0015).

update public.programs set title = title || $j${"es": "Empleado → Negocio"}$j$::jsonb, summary = summary || $j${"es": "Un trayecto guiado para dejar el empleo con los pies en la tierra: claridad, finanzas, validación, formalización y los primeros 90 días."}$j$::jsonb where slug = 'clt-para-negocio';
update public.program_lessons set title = title || $j${"es": "Claridad: por qué y para qué"}$j$::jsonb, body = body || $j${"es": "Antes de cualquier planilla, conviene entender qué quieres cambiar. Dejar un empleo suele ser la respuesta a una pregunta que aún no se formuló con claridad: ¿más libertad? ¿más ingresos? ¿más sentido? ¿otro ritmo de vida?\n\nNo existe un motivo correcto o incorrecto. Existen motivos que te sostienen cuando el camino se pone difícil, y motivos que desaparecen en la primera mala semana.\n\nEn esta etapa no decides nada. Solo escribes, con honestidad, de dónde sales y a dónde quieres llegar."}$j$::jsonb, steps = $j$[{"pt-BR": "Escrever em uma página por que quero mudar de vida profissional", "en": "Write one page on why I want to change my professional life", "es": "Escribir en una página por qué quiero cambiar de vida profesional"}, {"pt-BR": "Definir o que eu não abriria mão (valores, horários, renda mínima)", "en": "Define what I would not give up (values, hours, minimum income)", "es": "Definir lo que no cedería (valores, horarios, ingreso mínimo)"}, {"pt-BR": "Descrever como seria uma semana boa no meu negócio", "en": "Describe what a good week in my business would look like", "es": "Describir cómo sería una buena semana en mi negocio"}]$j$::jsonb where position = 0 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.program_lessons set title = title || $j${"es": "Tu punto de partida financiero"}$j$::jsonb, body = body || $j${"es": "La mayor causa de abandono del negocio al principio no es la falta de ideas: es la falta de aire. El dinero compra tiempo para aprender, equivocarse y ajustar.\n\nUsa el Plan Financiero de la app para ver tu costo mensual real (gastos + cuotas). Una referencia común es tener de 6 a 12 meses de ese costo ahorrados antes de depender del negocio. Si eso parece lejano, está bien: este trayecto existe justamente para construir el puente poco a poco.\n\nLas deudas caras (tarjeta, sobregiro) pesan más que casi cualquier otro riesgo. Suelen ir primero en la fila."}$j$::jsonb, steps = $j$[{"pt-BR": "Cadastrar rendas, despesas e dívidas no Plano Financeiro", "en": "Add income, expenses and debts to the Financial Plan", "es": "Registrar ingresos, gastos y deudas en el Plan Financiero"}, {"pt-BR": "Definir minha meta de reserva em meses de custo", "en": "Set my reserve goal in months of cost", "es": "Definir mi meta de reserva en meses de costo"}, {"pt-BR": "Escolher uma dívida cara para priorizar", "en": "Pick one expensive debt to prioritize", "es": "Elegir una deuda cara para priorizar"}]$j$::jsonb where position = 1 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.program_lessons set title = title || $j${"es": "Elegir la idea: problema, persona y oferta"}$j$::jsonb, body = body || $j${"es": "Los buenos negocios pequeños empiezan por un problema real de una persona específica, no por un producto bonito. Pregunta: ¿quién sufre con esto? ¿cuánto gasta ya (en dinero o tiempo) para resolverlo? ¿por qué me escucharía?\n\nUsa lo que ya tienes: experiencia laboral, contactos, habilidades. Quien cambia de carrera rara vez parte de cero; parte desde otro ángulo.\n\nElige una idea para probar, no \"la\" idea de tu vida. Probar es barato; acertar a la primera es raro."}$j$::jsonb, steps = $j$[{"pt-BR": "Listar 3 ideias de negócio ligadas ao que eu já sei fazer", "en": "List 3 business ideas tied to what I already know how to do", "es": "Listar 3 ideas de negocio ligadas a lo que ya sé hacer"}, {"pt-BR": "Descrever, para cada uma, quem é o cliente e qual problema resolve", "en": "For each, describe who the customer is and what problem it solves", "es": "Describir, para cada una, quién es el cliente y qué problema resuelve"}, {"pt-BR": "Escolher uma ideia para validar nas próximas semanas", "en": "Pick one idea to validate over the next weeks", "es": "Elegir una idea para validar en las próximas semanas"}]$j$::jsonb where position = 2 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.program_lessons set title = title || $j${"es": "Validar sin dejar el empleo"}$j$::jsonb, body = body || $j${"es": "Validar es descubrir si alguien paga por lo que ofreces antes de invertir mucho. La señal más fuerte es un cliente real pagando, aunque sea poco.\n\nEmpieza pequeño: conversa con cinco personas de tu público, ofrece una versión simple del servicio, vende a alguien conocido. Hazlo en las noches y fines de semana, respetando tu contrato y evitando conflictos con tu empleador.\n\nCada conversación enseña algo. El objetivo de esta etapa es la primera venta y lo que enseñó."}$j$::jsonb, steps = $j$[{"pt-BR": "Conversar com 5 pessoas do meu público-alvo", "en": "Talk to 5 people in my target audience", "es": "Conversar con 5 personas de mi público objetivo"}, {"pt-BR": "Montar uma oferta simples com preço", "en": "Put together a simple offer with a price", "es": "Armar una oferta simple con precio"}, {"pt-BR": "Fazer a primeira venda (mesmo pequena)", "en": "Make the first sale (even a small one)", "es": "Hacer la primera venta (aunque sea pequeña)"}]$j$::jsonb where position = 3 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.program_lessons set title = title || $j${"es": "Formalización, impuestos y tus derechos"}$j$::jsonb, body = body || $j${"es": "Este contenido es educativo y no reemplaza a un contador ni a un abogado. Las reglas cambian; confirma siempre los valores y límites vigentes.\n\nEn Brasil, muchos empiezan como MEI (límite anual de facturación y actividades permitidas definidos por ley) y luego pasan a ME en el Simples Nacional. Un contador ayuda a elegir el encuadre y a evitar sorpresas.\n\nSobre el empleo CLT: renunciar, ser despedido y hacer un acuerdo (art. 484-A) generan derechos distintos sobre FGTS, multa, preaviso y seguro de desempleo. Entiende esas diferencias antes de fijar la fecha de salida, pues cambia cuánto dinero de puente tendrás.\n\nSi estás fuera de Brasil, consulta a un contador local por el equivalente: estructura del negocio, impuestos y qué pierdes o conservas al dejar el empleo."}$j$::jsonb, steps = $j$[{"pt-BR": "Marcar uma conversa com um contador", "en": "Book a conversation with an accountant", "es": "Agendar una conversación con un contador"}, {"pt-BR": "Anotar o que muda no meu caso entre pedir demissão e acordo", "en": "Note what changes in my case between resigning and a mutual agreement", "es": "Anotar qué cambia en mi caso entre renunciar y acordar la salida"}, {"pt-BR": "Escolher o formato legal do negócio", "en": "Choose the legal structure of the business", "es": "Elegir la forma legal del negocio"}]$j$::jsonb where position = 4 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.program_lessons set title = title || $j${"es": "El plan de transición (90 días)"}$j$::jsonb, body = body || $j${"es": "Con la idea validada y los números sobre la mesa, define el puente: una fecha de salida, cuánta reserva tendrás para entonces, cuánto debe facturar el negocio para cubrir el costo mínimo y qué pasa si no llega ahí (plan B).\n\nLas transiciones graduales suelen ser más seguras: reducir la carga, negociar horarios, o salir solo cuando el negocio cubra parte del costo.\n\nConviértelo en proyecto: esta app crea un proyecto con los pasos prácticos del trayecto para que lo sigas y envíes pasos a tu día."}$j$::jsonb, steps = $j$[{"pt-BR": "Definir a data-alvo de saída e a reserva mínima nela", "en": "Set the target exit date and the minimum reserve by then", "es": "Definir la fecha objetivo de salida y la reserva mínima para entonces"}, {"pt-BR": "Calcular o faturamento mínimo mensal do negócio", "en": "Calculate the business's minimum monthly revenue", "es": "Calcular la facturación mínima mensual del negocio"}, {"pt-BR": "Escrever o plano B se a meta não for atingida", "en": "Write plan B if the goal is not met", "es": "Escribir el plan B si no se alcanza la meta"}]$j$::jsonb where position = 5 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.program_lessons set title = title || $j${"es": "Los primeros 90 días del negocio"}$j$::jsonb, body = body || $j${"es": "En los primeros meses, el trabajo es simple y exigente: vender, entregar bien, cobrar y separar el dinero de la empresa del tuyo.\n\nCrea una rutina fija de prospección (un poco cada día), registra lo que entra y sale, y aparta una parte de cada venta para impuestos. Revisa los números una vez por semana.\n\nEspera altibajos. Un mes flojo no es un veredicto; es información para ajustar oferta, precio o canal."}$j$::jsonb, steps = $j$[{"pt-BR": "Criar rotina diária de prospecção (30 min)", "en": "Create a daily prospecting routine (30 min)", "es": "Crear una rutina diaria de prospección (30 min)"}, {"pt-BR": "Abrir uma conta separada para o negócio", "en": "Open a separate account for the business", "es": "Abrir una cuenta separada para el negocio"}, {"pt-BR": "Reservar % de cada venda para impostos", "en": "Set aside a % of each sale for taxes", "es": "Apartar un % de cada venta para impuestos"}]$j$::jsonb where position = 6 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.program_lessons set title = title || $j${"es": "Cuidarte en la travesía"}$j$::jsonb, body = body || $j${"es": "Cambiar de vida mueve la identidad, la seguridad y las relaciones. Es normal sentir miedo, entusiasmo y duda el mismo día.\n\nMantén una red de apoyo: alguien que escuche sin intentar arreglar. Protege el sueño, el movimiento y el descanso, que sostienen cualquier plan. Usa la Gratitud y las Afirmaciones de la app como anclas diarias.\n\nSi en algún momento el camino pide ajustes, ajustar no es fracasar. Es planificar de nuevo con más información."}$j$::jsonb, steps = $j$[{"pt-BR": "Combinar com uma pessoa de confiança um check-in semanal", "en": "Agree on a weekly check-in with someone I trust", "es": "Acordar con una persona de confianza un chequeo semanal"}, {"pt-BR": "Definir uma prática diária de descanso ou movimento", "en": "Define a daily rest or movement practice", "es": "Definir una práctica diaria de descanso o movimiento"}, {"pt-BR": "Registrar uma gratidão por dia durante a transição", "en": "Log one gratitude a day during the transition", "es": "Registrar una gratitud al día durante la transición"}]$j$::jsonb where position = 7 and program_id = (select id from public.programs where slug = 'clt-para-negocio');
update public.programs set title = title || $j${"es": "Del sueño a la acción"}$j$::jsonb, summary = summary || $j${"es": "Tres lecciones cortas para usar Plano A de la forma correcta: sueño, hábito y revisión."}$j$::jsonb where slug = 'do-sonho-a-acao';
update public.program_lessons set title = title || $j${"es": "Sueño, meta, acción"}$j$::jsonb, body = body || $j${"es": "Un sueño se vuelve realidad cuando se traduce en metas con plazo y en acciones lo bastante pequeñas para caber en un día.\n\nEn Plano A el orden es este: registra el sueño (Sueños), declara dónde quieres estar en 6 meses, 1, 5 y 10 años (Metas) y elige hoy una acción (Mi Acción)."}$j$::jsonb, steps = $j$[{"pt-BR": "Registrar 3 sonhos", "en": "Record 3 dreams", "es": "Registrar 3 sueños"}, {"pt-BR": "Preencher os objetivos de 6 meses e 1 ano", "en": "Fill in the 6-month and 1-year goals", "es": "Completar las metas de 6 meses y 1 año"}, {"pt-BR": "Escolher uma ação para hoje", "en": "Pick one action for today", "es": "Elegir una acción para hoy"}]$j$::jsonb where position = 0 and program_id = (select id from public.programs where slug = 'do-sonho-a-acao');
update public.program_lessons set title = title || $j${"es": "Hábitos que sostienen el plan"}$j$::jsonb, body = body || $j${"es": "La motivación fluctúa; los hábitos permanecen. Elige un hábito pequeño, ligado a algo que ya haces todos los días, y protege la racha sin culpa: un día sin registro no borra lo que construiste."}$j$::jsonb, steps = $j$[{"pt-BR": "Criar um hábito de 2 minutos", "en": "Create a 2-minute habit", "es": "Crear un hábito de 2 minutos"}, {"pt-BR": "Ligar o hábito a um gatilho do dia", "en": "Tie the habit to a daily trigger", "es": "Ligar el hábito a un disparador del día"}]$j$::jsonb where position = 1 and program_id = (select id from public.programs where slug = 'do-sonho-a-acao');
update public.program_lessons set title = title || $j${"es": "Revisión semanal en 10 minutos"}$j$::jsonb, body = body || $j${"es": "Una vez por semana, mira lo que avanzó, lo que aprendiste y cuál es el siguiente paso. La página de Progreso muestra tu constancia sin marcar fallas: úsala como espejo, no como cobro."}$j$::jsonb, steps = $j$[{"pt-BR": "Marcar a revisão semanal na agenda", "en": "Put the weekly review on the calendar", "es": "Poner la revisión semanal en la agenda"}, {"pt-BR": "Escolher o foco da próxima semana", "en": "Choose next week's focus", "es": "Elegir el foco de la próxima semana"}]$j$::jsonb where position = 2 and program_id = (select id from public.programs where slug = 'do-sonho-a-acao');
update public.programs set title = title || $j${"es": "El día en que el sueño sucede"}$j$::jsonb, summary = summary || $j${"es": "Una visualización guiada de unos 8 minutos."}$j$::jsonb where slug = 'mentalizacao-dia-do-sonho';
update public.program_lessons set title = title || $j${"es": "Visualización: el día en que el sueño sucede"}$j$::jsonb, body = body || $j${"es": "Busca un lugar tranquilo y siéntate con la espalda cómoda. Cierra los ojos, si te resulta cómodo.\n\nRespira hondo tres veces, soltando el aire despacio. Siente el peso del cuerpo en el apoyo.\n\nElige uno de tus sueños. Imagina el día en que se cumple: ¿dónde estás? ¿quién está cerca? ¿qué ves, oyes y sientes en el cuerpo? Quédate en los detalles unos minutos, sin prisa y sin juzgar.\n\nAhora pregunta: ¿cuál es el paso más pequeño que puedo dar hoy hacia ese día? Deja que la respuesta surja.\n\nRespira hondo una vez más y, cuando quieras, abre los ojos. Anota el paso en la app."}$j$::jsonb, steps = $j$[{"pt-BR": "Anotar o passo que surgiu como ação de hoje", "en": "Write down the step that came up as today's action", "es": "Anotar el paso que surgió como acción de hoy"}]$j$::jsonb where position = 0 and program_id = (select id from public.programs where slug = 'mentalizacao-dia-do-sonho');
